const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a polygon for the Paraná River Delta region.
  // This polygon roughly covers the delta area in Argentina.
  const paranaDelta = ee.Geometry.Polygon(
    [
      [-61.0, -32.0], // Northwest
      [-57.5, -32.0], // Northeast
      [-57.5, -35.0], // Southeast
      [-61.0, -35.0]  // Southwest
    ]
  );

  const startDate2019 = '2019-01-01';
  const endDate2019 = '2019-07-22';
  const startDate2020 = '2020-01-01';
  const endDate2020 = '2020-07-22';

  // 2. Data Acquisition
  // Use MODIS Thermal Anomalies/Fire Daily (MCD14ML, Collection 5.1) for fire points.
  // This dataset provides individual fire detections as points.
  const fires = ee.ImageCollection('MODIS/051/MCD14ML');

  // Filter for 2019
  const fires2019 = fires
    .filterDate(startDate2019, endDate2019)
    .filterBounds(paranaDelta);

  // Filter for 2020
  const fires2020 = fires
    .filterDate(startDate2020, endDate2020)
    .filterBounds(paranaDelta);

  // Get the number of hotspots
  let count2019, count2020;

  try {
    count2019 = await fires2019.size().getInfo();
    count2020 = await fires2020.size().getInfo();
  } catch (e) {
    console.log(`Error retrieving collection size: ${e}`);
    console.log("D"); // General error
    return;
  }

  // 3. Validation and Check for Empty Collections (C1)
  if (count2019 === 0 && count2020 === 0) {
    console.log(`2019 Images: 0`);
    console.log(`2020 Images: 0`);
    console.log("C1"); // No images found for either period
    return;
  } else if (count2019 === 0) {
    console.log(`2019 Images: 0`);
    console.log(`2020 Images: ${count2020}`);
    console.log("C1"); // No images found for 2019 period
    return;
  } else if (count2020 === 0) {
    console.log(`2019 Images: ${count2019}`);
    console.log(`2020 Images: 0`);
    console.log("C1"); // No images found for 2020 period
    return;
  }

  // 4. Calculation & Comparison
  console.log(`2019 Hotspots: ${count2019}`);
  console.log(`2020 Hotspots: ${count2020}`);

  // Check if count is None or NaN (though size().getInfo() typically returns a number)
  if (typeof count2019 !== 'number' || typeof count2020 !== 'number' || isNaN(count2019) || isNaN(count2020)) {
    console.log("C3"); // Calculation failure if results are not valid numbers
    return;
  }

  const exceeds = count2020 > count2019;

  // 5. Final Answer
  if (exceeds) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
